# Solution: Socket-Based Background Indexing for Knowledge Settings

I'll help you implement socket event-based background indexing. Here's the complete solution:

## 1. Backend: Socket Handler for Knowledge Indexing

```py api/codx/junior/sio/sio.py
@sio.on("codx-junior-index-knowledge")
@sio_api_endpoint
async def sio_index_knowledge(sid, data: dict, codxjunior_session: CODXJuniorSession):
    """
    Index knowledge files in the background via socket event.

    Expected data:
        - file_paths: List[str] - Absolute paths to files/folders to index
        - codx_path: str - Project path
    """
    file_paths = data.get("file_paths", [])
    logger.info(f"Socket: index_knowledge | files={len(file_paths)} | project={codxjunior_session.settings.project_name}")

    try:
        # Index files in background
        result = codxjunior_session.knowledge_engine.index_knowledge_source(
            sources=file_paths
        )

        # Notify client of completion
        channel = SessionChannel(sio=sio, sid=sid)
        channel.send_event('codx-junior-index-knowledge-complete', {
            "status": "success",
            "files_indexed": len(file_paths),
            "message": f"Successfully indexed {len(file_paths)} file(s)"
        })

        logger.info(f"Socket: index_knowledge complete | files={len(file_paths)}")
        return result

    except Exception as ex:
        logger.exception("Error indexing knowledge via socket")
        channel = SessionChannel(sio=sio, sid=sid)
        channel.send_event('codx-junior-index-knowledge-error', {
            "status": "error",
            "message": str(ex)
        })
        return {"error": str(ex)}
```

## 2. Frontend: JavaScript API Addition

```js client/src/api/api.js
knowledge: {
  status() {
    return API.get('/api/knowledge/status')
  },
  files() {
    return API.get('/api/knowledge/files')
  },
  reload() {
    return API.get('/api/knowledge/reload')
  },
  reloadFolder(path) {
    return API.post(`/api/knowledge/reload-path`, { path })
  },
  // NEW: Socket-based background indexing
  indexFilesBackground(filePaths) {
    if (!API.socket) {
      throw new Error('Socket not connected')
    }
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        reject(new Error('Index operation timed out'))
      }, 30000)

      API.socket.emit('codx-junior-index-knowledge', {
        file_paths: filePaths,
        codx_path: API.activeProject?.codx_path
      }, (response) => {
        clearTimeout(timeoutId)
        if (response?.error) {
          reject(new Error(response.error))
        } else {
          resolve(response)
        }
      })
    })
  },
  search({
    searchTerm: search_term,
    searchType: search_type,
    documentSearchType: document_search_type,
    cutoffScore: document_cutoff_score,
    cutoffRag: document_cutoff_rag,
    documentCount: document_count
  }) {
    return API.post(`/api/knowledge/reload-search`, {
      search_term,
      search_type,
      document_search_type,
      document_cutoff_score,
      document_cutoff_rag,
      document_count
    })
  },
  aiSearch(query) {
    return API.get(`/api/knowledge/ai-search?query=${encodeURIComponent(query)}`)
  },
  delete(sources) {
    return API.post(`/api/knowledge/delete`, { sources })
  },
  deleteIndex(index) {
    return API.del(`/api/knowledge/delete?index=${index}`)
  },
  keywords() {
    return API.get(`/api/knowledge/keywords`)
  },
  searchKeywords(searchQuery) {
    return API.get(`/api/knowledge/keywords?query=${searchQuery}`)
  },
  query(searchQuery) {
    return API.get(`/api/project/search?query=${searchQuery}`)
  },
  summary() {
    return API.get(`/api/knowledge/summary`)
  },
  rebuildSummary() {
    return API.post(`/api/knowledge/summary/rebuild`, {})
  },
  deleteSummary() {
    return API.delete(`/api/knowledge/summary`)
  }
},
